    private fun e(
        id: String,
        type: String,
        label: String,
        dataSource: String,
        action: String,
        enabledWhen: String = "authenticated session and current state allow the action",
        validation: String = "none",
        confirmation: String = "none",
        backend: String = "user-scoped PostgREST/RPC contract",
        databaseEffect: String = "read-only unless an explicit RPC is listed",
    ) = CustomerUiElementContract(
        elementId = id,
        screenId = id.substringBefore('.'),
        parentId = id.substringBeforeLast('.'),
        type = type,
        label = label,
        visualRole = if (type == "button") "action" else "information",
        dataSource = dataSource,
        action = action,
        enabledWhen = enabledWhen,
        validation = validation,
        backend = backend,
        databaseEffect = databaseEffect,
        accessibility = label,
    )
